      "content": "{\n  \"name\": \"dsh-tool-budget\",\n  \"version\": \"0.1.2\",\n  \"description\": \"Hard-stop DeepSeek Harness tool use after a per-session call budget.\",\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"https://github.com/173787247/dsh-tool-budget.git\"\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/173787247/dsh-tool-budget/issues\"\n  },\n  \"homepage\": \"https://github.com/173787247/dsh-tool-budget#readme\",\n  \"type\": \"module\",\n  \"main\": \"index.js\",\n  \"engines\": {\n    \"node\": \">=18\"\n  },\n  \"scripts\": {\n    \"test\": \"node --test test/budget.test.js test/apply.test.js\"\n  },\n  \"files\": [\n    \"index.js\",\n    \"lib\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README.zh.md\",\n    \"LICENSE\",\n    \"CHANGELOG.md\"\n  ],\n  \"keywords\": [\n    \"dsh-plugin\",\n    \"deepseek-harness\",\n    \"budget\",\n    \"safety\",\n    \"wsl\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    }\n  }\n}\n"
