      "path": "cordis.patch.yml",
      "content": "# Default dsh-tool-budget config for DeepSeek Harness profiles.\n# Later layers that redefine this plugin config replace the whole object.\n- insert:\n    - id: dsh-tool-budget\n      name: dsh-tool-budget\n      config:\n        enabled: true\n        maxCalls: 80\n        exclude:\n          - job_output\n          - job_list\n          - job_kill"
    },
